package com.vit.archds.entity; import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="optimization_results") public class OptimizationResult { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @OneToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="job_id",unique=true) private AnalysisJob job; @Column(nullable=false) private String algorithm; @Lob private String objectivesJson; @Lob private String paretoCandidateIdsJson; @Lob private String tradeoffsJson; @Column(nullable=false) private Instant createdAt=Instant.now(); public OptimizationResult(){} public OptimizationResult(AnalysisJob j,String a,String o,String p,String t){job=j;algorithm=a;objectivesJson=o;paretoCandidateIdsJson=p;tradeoffsJson=t;} public String getAlgorithm(){return algorithm;} public String getObjectivesJson(){return objectivesJson;} public String getParetoCandidateIdsJson(){return paretoCandidateIdsJson;} public String getTradeoffsJson(){return tradeoffsJson;} }
